def predict(board, action):
    if isinstance(action, tuple):
        row, col = action
    else:
        row, col = action[0], action[1]

    old_char = board[row][col]
    new_char = 'B' if old_char == 'b' else 'c' if old_char == 'b' else old_char

    board[row][col] = new_char

    if old_char == 'b':
        for i in range(row-1, row+2):
            for j in range(col-1, col+2):
                if 0 <= i < 64 and 0 <= j < 64:
                    if board[i][j] == 'b':
                        board[i][j] = new_char

    return ["".join(row) for row in board]
